	inv, err := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: c.ID, Currency: money.EUR, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 100}}, TaxRateBP: 5}, t0)
	if err != nil {
		t.Fatal(err)
	}
