// InvoiceKey is a position in an organization's invoice list: the invoice with this creation time and ID.
type InvoiceKey struct {
	CreatedAt time.Time
	ID        string
}

// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
	page, _ := s.InvoicePage(orgID, f, nil, len(s.invoices))
	return page
}

// InvoicePage returns up to limit of an organization's invoices that match f and come after after (nil for the first page),
// oldest first (ties by ID). more reports whether a matching invoice follows the page.
func (s *Store) InvoicePage(orgID string, f InvoiceFilter, after *InvoiceKey, limit int) (page []Invoice, more bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	ids := s.invoiceOrder[orgID]
	start := 0
	if after != nil {
		start = sort.Search(len(ids), func(i int) bool {
			o := s.invoices[ids[i]]
			return keyBefore(after.CreatedAt, after.ID, o.CreatedAt, o.ID)
		})
	}
	page = []Invoice{}
	for _, id := range ids[start:] {
		inv := s.invoices[id]
		if (f.CustomerID != "" && inv.CustomerID != f.CustomerID) || (f.SubscriptionID != "" && inv.SubscriptionID != f.SubscriptionID) || (f.Status != "" && inv.Status != f.Status) {
			continue
		}
		if len(page) == limit {
			return page, true
		}
		page = append(page, cloneInvoice(inv))
	}
	return page, false
}

// keyBefore orders invoices by creation time, then ID.
func keyBefore(t1 time.Time, id1 string, t2 time.Time, id2 string) bool {
	if !t1.Equal(t2) {
		return t1.Before(t2)
	}
	return id1 < id2
}

// indexInvoice adds a stored invoice to its organization's order. The caller holds the lock.
func (s *Store) indexInvoice(inv Invoice) {
	ids := s.invoiceOrder[inv.OrgID]
	i := sort.Search(len(ids), func(i int) bool {
		o := s.invoices[ids[i]]
		return keyBefore(inv.CreatedAt, inv.ID, o.CreatedAt, o.ID)
	})
	ids = append(ids, "")
	copy(ids[i+1:], ids[i:])
	ids[i] = inv.ID
	s.invoiceOrder[inv.OrgID] = ids
}

