package store

import (
	"encoding/json"
	"sort"
	"testing"
	"time"

	"example.com/tally/internal/money"
)

// expectedInvoices is the answer for a filter, worked out from the exported state rather than the index.
func expectedInvoices(s *Store, orgID string, f InvoiceFilter) []Invoice {
	out := []Invoice{}
	for _, inv := range s.Export().Invoices {
		if inv.OrgID != orgID || (f.CustomerID != "" && inv.CustomerID != f.CustomerID) || (f.SubscriptionID != "" && inv.SubscriptionID != f.SubscriptionID) || (f.Status != "" && inv.Status != f.Status) {
			continue
		}
		out = append(out, inv)
	}
	sort.Slice(out, func(i, j int) bool { return keyBefore(out[i].CreatedAt, out[i].ID, out[j].CreatedAt, out[j].ID) })
	return out
}

// walkPages follows next cursors from the first page, calling between after each page that is not the last.
func walkPages(t *testing.T, s *Store, orgID string, f InvoiceFilter, limit int, between func()) []Invoice {
	t.Helper()
	got := []Invoice{}
	var after *InvoiceKey
	for pages := 0; ; pages++ {
		if pages > 1000 {
			t.Fatal("the pages never end")
		}
		page, more := s.InvoicePage(orgID, f, after, limit)
		if len(page) > limit {
			t.Fatalf("a page has %d invoices, limit %d", len(page), limit)
		}
		got = append(got, page...)
		if !more {
			return got
		}
		last := page[len(page)-1]
		after = &InvoiceKey{CreatedAt: last.CreatedAt, ID: last.ID}
		if between != nil {
			between()
		}
	}
}

func sameInvoices(t *testing.T, what string, got, want []Invoice) {
	t.Helper()
	gb, _ := json.Marshal(got)
	wb, _ := json.Marshal(want)
	if string(gb) != string(wb) {
		t.Fatalf("%s:\ngot  %s\nwant %s", what, gb, wb)
	}
}

func TestInvoicePagesMatchTheOrder(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	b := newOrg(t, s, "B")
	jane, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	john, _ := s.CreateCustomer(a.ID, "John", "john@example.com", t0)
	other, _ := s.CreateCustomer(b.ID, "Other", "other@example.com", t0)
	line := []Line{{Description: "x", Quantity: 1, UnitAmount: 100}}
	for i := 0; i < 60; i++ {
		// Creation times repeat and go backwards, so ties and out-of-order inserts both happen.
		at := t0.Add(time.Duration(i*7%5) * time.Minute)
		if i%6 == 5 {
			_, _ = s.CreateInvoice(Invoice{OrgID: b.ID, CustomerID: other.ID, Currency: money.USD, Lines: line}, at)
			continue
		}
		cust, sub := jane, ""
		if i%3 == 0 {
			cust = john
		}
		if i%4 == 0 {
			sub = "sub_1"
		}
		inv, err := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: cust.ID, SubscriptionID: sub, Currency: money.USD, Lines: line}, at)
		if err != nil {
			t.Fatal(err)
		}
		if i%7 == 0 {
			_, _ = s.UpdateInvoice(a.ID, inv.ID, func(i *Invoice) error { i.Status, i.PaidAt = InvoicePaid, &at; return nil })
		} else if i%9 == 0 {
			_, _ = s.UpdateInvoice(a.ID, inv.ID, func(i *Invoice) error { i.Status, i.VoidedAt = InvoiceVoid, &at; return nil })
		}
	}
	filters := []InvoiceFilter{
		{},
		{CustomerID: jane.ID},
		{CustomerID: john.ID},
		{SubscriptionID: "sub_1"},
		{Status: InvoiceOpen},
		{Status: InvoicePaid},
		{Status: InvoiceVoid},
		{CustomerID: john.ID, Status: InvoiceOpen},
		{CustomerID: other.ID},
		{CustomerID: "cus_missing"},
	}
	s2, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	for _, f := range filters {
		want := expectedInvoices(s, a.ID, f)
		for _, limit := range []int{1, 3, 7, 100} {
			sameInvoices(t, "pages", walkPages(t, s, a.ID, f, limit, nil), want)
			sameInvoices(t, "pages after FromState", walkPages(t, s2, a.ID, f, limit, nil), want)
		}
		sameInvoices(t, "ListInvoices", s.ListInvoices(a.ID, f), want)
	}
	if got := s.ListInvoices(b.ID, InvoiceFilter{}); len(got) != 10 || got[0].OrgID != b.ID {
		t.Fatalf("another organization's invoices = %d", len(got))
	}
}

func TestInvoicePagesSeeNewInvoices(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	c, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	line := []Line{{Description: "x", Quantity: 1, UnitAmount: 100}}
	for i := 0; i < 10; i++ {
		_, _ = s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: c.ID, Currency: money.USD, Lines: line}, t0.Add(time.Minute))
	}
	// New invoices are created between pages: earlier-dated ones land after the cursor, later ones at the end.
	created := 0
	got := walkPages(t, s, a.ID, InvoiceFilter{}, 4, func() {
		created++
		_, _ = s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: c.ID, Currency: money.USD, Lines: line}, t0.Add(time.Duration(created)*time.Hour))
		_, _ = s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: c.ID, Currency: money.USD, Lines: line}, t0)
	})
	sameInvoices(t, "pages with new invoices", got, expectedInvoices(s, a.ID, InvoiceFilter{}))
	if len(got) != 10+2*created {
		t.Fatalf("got %d invoices, want %d", len(got), 10+2*created)
	}
}

