package api_test

import (
	"fmt"
	"net/http"
	"sort"
	"strings"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// listedInvoice is the part of an invoice list item these tests read.
type listedInvoice struct {
	ID        string    `json:"id"`
	CreatedAt time.Time `json:"created_at"`
	Status    string    `json:"status"`
	Total     int64     `json:"total"`
	Description string `json:"description"`
	Customer  *struct {
		ID   string `json:"id"`
		Name string `json:"name"`
	} `json:"customer"`
}

type invoicePage struct {
	Items      []listedInvoice `json:"items"`
	NextCursor string          `json:"next_cursor"`
}

// walkInvoices follows next_cursor from the first page and returns every item in order.
func walkInvoices(t *testing.T, e *apitest.Env, org apitest.Org, query string, limit int, between func()) []listedInvoice {
	t.Helper()
	var all []listedInvoice
	cursor := ""
	for pages := 0; ; pages++ {
		if pages > 1000 {
			t.Fatal("the pages never end")
		}
		path := fmt.Sprintf("/v1/invoices?limit=%d&%s", limit, query)
		if cursor != "" {
			path += "&cursor=" + cursor
		}
		var p invoicePage
		e.MustDo(http.StatusOK, "GET", path, org.Key, nil, &p)
		all = append(all, p.Items...)
		if p.NextCursor == "" {
			return all
		}
		cursor = p.NextCursor
		if between != nil {
			between()
		}
	}
}

func TestInvoiceListPaging(t *testing.T) {
	e := apitest.New(t)
	jane := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	john := e.CreateCustomer(e.Acme, "John", "john@example.com")
	other := e.CreateCustomer(e.Globex, "Other", "other@example.com")
	create := func(org apitest.Org, c store.Customer, n int) {
		for i := 0; i < n; i++ {
			e.MustDo(http.StatusCreated, "POST", "/v1/invoices", org.Key, map[string]any{"customer_id": c.ID, "currency": "USD",
				"lines": []any{map[string]any{"description": fmt.Sprintf("item %d", i), "quantity": 1, "unit_amount": 500}}}, nil)
		}
	}
	// Invoices made in the same instant share a creation time, so their order is by ID.
	create(e.Acme, jane, 7)
	e.Clock.Advance(time.Minute)
	create(e.Acme, john, 6)
	create(e.Globex, other, 4)
	e.Clock.Advance(time.Hour)
	create(e.Acme, jane, 3)
	var voided invoicePage
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?limit=100", e.Acme.Key, nil, &voided)
	e.MustDo(http.StatusOK, "POST", "/v1/invoices/"+voided.Items[2].ID+"/void", e.Acme.Key, nil, nil)

	queries := []string{"", "customer_id=" + jane.ID, "customer_id=" + john.ID, "customer_id=" + other.ID, "status=open", "status=void",
		"status=paid", "customer_id=" + jane.ID + "&status=open", "subscription_id=sub_none"}
	for _, q := range queries {
		want := walkInvoices(t, e, e.Acme, q, 100, nil)
		for _, limit := range []int{1, 4, 20} {
			got := walkInvoices(t, e, e.Acme, q, limit, nil)
			if fmt.Sprint(ids(got)) != fmt.Sprint(ids(want)) {
				t.Fatalf("%q with limit %d:\ngot  %v\nwant %v", q, limit, ids(got), ids(want))
			}
		}
		if !sort.SliceIsSorted(want, func(i, j int) bool {
			if !want[i].CreatedAt.Equal(want[j].CreatedAt) {
				return want[i].CreatedAt.Before(want[j].CreatedAt)
			}
			return want[i].ID < want[j].ID
		}) {
			t.Fatalf("%q is not oldest first: %v", q, ids(want))
		}
		for _, inv := range want {
			if inv.Customer == nil || inv.Description == "" || inv.Total != 500 {
				t.Fatalf("%q: item %+v is missing its customer or totals", q, inv)
			}
		}
	}
	if got := walkInvoices(t, e, e.Acme, "customer_id="+jane.ID, 100, nil); len(got) != 10 || got[0].Customer.Name != "Jane" {
		t.Fatalf("Jane's invoices = %d", len(got))
	}

	// Invoices created between pages are listed after the cursor, and nothing is listed twice.
	before := walkInvoices(t, e, e.Acme, "", 100, nil)
	created := 0
	got := walkInvoices(t, e, e.Acme, "", 3, func() {
		created++
		e.Clock.Advance(time.Minute)
		create(e.Acme, john, 1)
	})
	if len(got) != len(before)+created {
		t.Fatalf("got %d invoices, want %d", len(got), len(before)+created)
	}
	seen := map[string]bool{}
	for _, inv := range got {
		if seen[inv.ID] {
			t.Fatalf("invoice %s listed twice", inv.ID)
		}
		seen[inv.ID] = true
	}

	for _, path := range []string{"/v1/invoices?limit=0", "/v1/invoices?limit=101", "/v1/invoices?cursor=nope", "/v1/invoices?status=lost"} {
		if r := e.Do("GET", path, e.Acme.Key, nil); r.Code != http.StatusBadRequest {
			t.Fatalf("%s: %s", path, r)
		}
	}
	if r := e.Do("GET", "/v1/invoices", "", nil); r.Code != http.StatusUnauthorized {
		t.Fatalf("no key: %s", r)
	}
}

func ids(items []listedInvoice) []string {
	out := []string{}
	for _, inv := range items {
		out = append(out, inv.ID)
	}
	return out
}

// TestInvoiceListWithManyInvoices checks the list of a large organization stays fast, with other organizations' invoices
// in the store too. It creates the records directly, which is quicker than the API.
func TestInvoiceListWithManyInvoices(t *testing.T) {
	if testing.Short() {
		t.Skip("builds 60,000 invoices")
	}
	e := apitest.New(t)
	now := e.Clock.Now()
	customers := make([]store.Customer, 0, 5000)
	for i := 0; i < 5000; i++ {
		c, err := e.Store.CreateCustomer(e.Acme.ID, fmt.Sprintf("Customer %d", i), fmt.Sprintf("c%d@example.com", i), now)
		if err != nil {
			t.Fatal(err)
		}
		customers = append(customers, c)
	}
	otherCustomer, _ := e.Store.CreateCustomer(e.Globex.ID, "Other", "other@example.com", now)
	line := []store.Line{{Description: "Seats", Quantity: 2, UnitAmount: 1500}}
	for i := 0; i < 60000; i++ {
		inv := store.Invoice{OrgID: e.Acme.ID, CustomerID: customers[i%len(customers)].ID, Currency: money.USD, Lines: line}
		if i%10 == 0 {
			inv.SubscriptionID = "sub_renewals"
		}
		// Creation times repeat in blocks of 100, and the clock goes forward once per block.
		at := now.Add(time.Duration(i/100) * time.Second)
		if _, err := e.Store.CreateInvoice(inv, at); err != nil {
			t.Fatal(err)
		}
		if i%5 == 0 {
			_, _ = e.Store.CreateInvoice(store.Invoice{OrgID: e.Globex.ID, CustomerID: otherCustomer.ID, Currency: money.USD, Lines: line}, at)
		}
	}
	const budget = 250 * time.Millisecond
	for _, q := range []string{"", "customer_id=" + customers[7].ID, "subscription_id=sub_renewals", "status=open", "status=void"} {
		for _, path := range []string{"/v1/invoices?" + q, "/v1/invoices?limit=100&" + q} {
			start := time.Now()
			r := e.Do("GET", path, e.Acme.Key, nil)
			took := time.Since(start)
			if r.Code != http.StatusOK {
				t.Fatalf("%s: %s", path, r)
			}
			if took > budget {
				t.Errorf("%s took %v, budget %v", path, took, budget)
			}
		}
	}
	// A page from the far end of the list, reached through its cursor.
	far := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{})
	last := far[len(far)-1000]
	cursor := encodeTestCursor(last)
	start := time.Now()
	r := e.Do("GET", "/v1/invoices?cursor="+cursor, e.Acme.Key, nil)
	if took := time.Since(start); took > budget || r.Code != http.StatusOK {
		t.Errorf("deep page: %v, %s", took, r)
	}
	if !strings.Contains(r.String(), last.ID) == false {
		t.Logf("deep page starts after %s", last.ID)
	}
}

