59	// listInvoices lists the organization's invoices, oldest first, optionally only those of ?customer_id=, ?subscription_id=
60	// or with ?status=.
61	func (s *Server) listInvoices(w http.ResponseWriter, r *http.Request, p auth.Principal) {
62		pg, ok := parsePage(w, r)
63		if !ok {
64			return
65		}
66		q := r.URL.Query()
67		status := store.InvoiceStatus(q.Get("status"))
68		if status != "" && status != store.InvoiceOpen && status != store.InvoicePaid && status != store.InvoiceVoid {
69			writeError(w, http.StatusBadRequest, "invalid_status", "status is open, paid or void")
70			return
71		}
72		f := store.InvoiceFilter{CustomerID: q.Get("customer_id"), SubscriptionID: q.Get("subscription_id"), Status: status}
73		var after *store.InvoiceKey
74		if pg.after != nil {
75			after = &store.InvoiceKey{CreatedAt: pg.after.T, ID: pg.after.ID}
76		}
77		invs, more := s.store.InvoicePage(p.OrgID, f, after, pg.limit)
78		views := make([]invoiceView, 0, len(invs))
79		for _, inv := range invs {
80			views = append(views, s.viewInvoice(inv))
81		}
82		next := ""
83		if more && len(views) > 0 {
84			next = encodeCursor(invoiceViewKey(views[len(views)-1]))
85		}
86		writeJSON(w, http.StatusOK, list{Items: views, NextCursor: next})
87	}
