89	func (s *Server) createInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
90		var in struct {
91			CustomerID      string         `json:"customer_id"`
92			Currency        money.Currency `json:"currency"`
93			Lines           []store.Line   `json:"lines"`
94			DiscountPercent int            `json:"discount_percent"`
95		}
96		if !decode(w, r, &in) {
97			return
98		}
99		if len(in.Lines) == 0 {
100			writeError(w, http.StatusUnprocessableEntity, "invalid", "an invoice needs at least one line")
101			return
102		}
103		for _, l := range in.Lines {
104			if strings.TrimSpace(l.Description) == "" || l.Quantity <= 0 || l.UnitAmount < 0 {
105				writeError(w, http.StatusUnprocessableEntity, "invalid", "each line needs a description, a positive quantity and a unit amount that is not negative")
106				return
107			}
108		}
109		inv, err := s.store.CreateInvoice(store.Invoice{OrgID: p.OrgID, CustomerID: in.CustomerID, Currency: in.Currency, Lines: in.Lines, DiscountPercent: in.DiscountPercent}, s.clock.Now())
110		if err != nil {
111			if errors.Is(err, store.ErrCustomerOrgMismatch) {
112				writeError(w, http.StatusUnprocessableEntity, "customer_org_mismatch", fmt.Sprintf("customer %s belongs to another organization", in.CustomerID))
113				return
114			}
115			s.storeError(w, err)
116			return
117		}
118		s.publish(r.Context(), p.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID})
119		writeJSON(w, http.StatusCreated, s.viewInvoice(inv))
120	}
