123		inv, ok := s.store.Invoice(p.OrgID, r.PathValue("id"))
124		if !ok {
125			writeError(w, http.StatusNotFound, "not_found", "no such invoice")
126			return
127		}
128		writeJSON(w, http.StatusOK, s.viewInvoice(inv))
129	}
