131	// getInvoiceLines answers an invoice's lines with each line's amount, for the dashboard's invoice table.
132	func (s *Server) getInvoiceLines(w http.ResponseWriter, r *http.Request, p auth.Principal) {
133		inv, ok := s.store.InvoiceByID(r.PathValue("id"))
134		if !ok {
135			writeError(w, http.StatusNotFound, "not_found", "no such invoice")
136			return
137		}
138		type lineView struct {
139			store.Line
140			Amount int64 `json:"amount"`
141		}
142		items := []lineView{}
143		for _, l := range inv.Lines {
144			items = append(items, lineView{Line: l, Amount: l.Amount()})
145		}
146		writeJSON(w, http.StatusOK, list{Items: items})
147	}
148	
149	// payInvoice charges an invoice: {"payment_method": "pm_..."}, or the customer's default payment method when it is absent.
150	func (s *Server) payInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
151		var in struct {
152			PaymentMethod string `json:"payment_method"`
153		}
154		if r.ContentLength != 0 && !decode(w, r, &in) {
155			return
156		}
157		inv, pay, err := s.pay.Pay(r.Context(), p.OrgID, r.PathValue("id"), in.PaymentMethod)
158		if err != nil {
159			s.payError(w, err)
160			return
161		}
162		writeJSON(w, http.StatusOK, map[string]any{"invoice": s.viewInvoice(inv), "payment": pay})
163	}
164	
165	func (s *Server) payError(w http.ResponseWriter, err error) {
166		var decline *payments.DeclineError
167		switch {
168		case errors.As(err, &decline):
169			writeJSON(w, http.StatusPaymentRequired, map[string]string{"error": "payment_declined", "decline_code": decline.Code, "message": err.Error()})
170		case errors.Is(err, payments.ErrAlreadyPaid):
171			writeError(w, http.StatusConflict, "already_paid", err.Error())
172		case errors.Is(err, payments.ErrInvoiceVoid):
173			writeError(w, http.StatusConflict, "invoice_void", err.Error())
174		case errors.Is(err, payments.ErrNoPaymentMethod):
175			writeError(w, http.StatusUnprocessableEntity, "no_payment_method", err.Error())
176		case errors.Is(err, payments.ErrUnavailable):
177			writeError(w, http.StatusServiceUnavailable, "gateway_unavailable", "the payment gateway is unavailable; nothing was charged, try again")
178		default:
179			s.storeError(w, err)
180		}
181	}
182	
183	func (s *Server) voidInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
184		now := s.clock.Now()
185		inv, err := s.store.UpdateInvoice(p.OrgID, r.PathValue("id"), func(inv *store.Invoice) error {
186			switch inv.Status {
187			case store.InvoicePaid:
188				return payments.ErrAlreadyPaid
189			case store.InvoiceVoid:
190				return payments.ErrInvoiceVoid
191			}
192			inv.Status, inv.VoidedAt = store.InvoiceVoid, &now
193			return nil
194		})
195		if err != nil {
196			s.payError(w, err)
197			return
198		}
199		s.publish(r.Context(), p.OrgID, "invoice.voided", map[string]any{"invoice_id": inv.ID})
200		writeJSON(w, http.StatusOK, s.viewInvoice(inv))
201	}
202	
203	func (s *Server) listPayments(w http.ResponseWriter, r *http.Request, p auth.Principal) {
204		writeJSON(w, http.StatusOK, list{Items: s.store.Payments(p.OrgID, r.URL.Query().Get("invoice_id"))})
205	}
