245	// CreateInvoice stores an invoice for one of the organization's customers, with the organization's tax rate. It is open.
246	func (s *Store) CreateInvoice(inv Invoice, now time.Time) (Invoice, error) {
247		if !inv.Currency.Valid() {
248			return Invoice{}, invalid("unknown currency %q", inv.Currency)
249		}
250		if inv.DiscountPercent < 0 || inv.DiscountPercent > 100 {
251			return Invoice{}, invalid("the discount is 0 to 100 percent")
252		}
253		for _, l := range inv.Lines {
254			if l.Quantity <= 0 {
255				return Invoice{}, invalid("a line needs a positive quantity")
256			}
257		}
258		s.mu.Lock()
259		defer s.mu.Unlock()
260		org, ok := s.orgs[inv.OrgID]
261		if !ok {
262			return Invoice{}, ErrNotFound
263		}
264		c, ok := s.customers[inv.CustomerID]
265		if !ok {
266			return Invoice{}, ErrNotFound
267		}
268		if c.OrgID != inv.OrgID {
269			return Invoice{}, ErrCustomerOrgMismatch
270		}
271		inv.ID = s.newID("in")
272		inv.TaxRateBP = org.TaxRateBP
273		inv.Status = InvoiceOpen
274		inv.CreatedAt = now.UTC()
275		inv.PaidAt, inv.VoidedAt = nil, nil
276		inv = copyInvoice(inv)
277		s.invoices[inv.ID] = inv
278		s.indexInvoice(inv)
279		return copyInvoice(inv), nil
280	}
